def transform(grid):
    h, w = len(grid), len(grid[0])

    # Full uniform rows and columns mark the boundaries between tiles.
    sep_rows = {r for r in range(h) if len(set(grid[r])) == 1}
    sep_cols = {
        c for c in range(w)
        if len({grid[r][c] for r in range(h)}) == 1
    }

    row_groups, col_groups = [], []
    start = 0
    for r in range(h):
        if r in sep_rows:
            if start < r:
                row_groups.append(range(start, r))
            start = r + 1
    if start < h:
        row_groups.append(range(start, h))

    start = 0
    for c in range(w):
        if c in sep_cols:
            if start < c:
                col_groups.append(range(start, c))
            start = c + 1
    if start < w:
        col_groups.append(range(start, w))

    from collections import Counter
    counts = Counter(
        grid[r][c]
        for rows in row_groups
        for r in rows
        for cols in col_groups
        for c in cols
    )
    background = counts.most_common(1)[0][0]
    signal = next((color for color in counts if color != background), background)

    return [
        [
            1 if sum(grid[r][c] == signal for r in rows for c in cols) >= 2
            else background
            for cols in col_groups
        ]
        for rows in row_groups
    ]
